function normalizeCutTypes(value){
  return [...new Map(String(value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean)
    .map(line=>[Jp(line),line])).values()];
}
const marcador = '\n\n[HA:tipos-de-corte]';
const marcadorEstilos = '\n\n[HA:estilos-de-bordado]';
const chaveCorte = nome => String(nome || '').trim().normalize('NFC').toLowerCase();

const clesioCutTypes=["PLANGECON","PLANGECON serviço indústriais"];
function isClesioClient(name){return Jp(name)==="clesio"}
function isClientCutAllowed(name,type){
  return isClesioClient(name)||!clesioCutTypes.some(reserved=>Jp(reserved)===Jp(type));
}
function readClientNotes(valor) {
  const notes = String(valor || '');
  const i = notes.lastIndexOf(marcador);
  if (i >= 0) {
    try {
      const catalog = JSON.parse(notes.slice(i + marcador.length));
      const cutTypes = Array.isArray(catalog)?catalog:catalog?.types;
      const cutPrices = Array.isArray(catalog?.prices)?catalog.prices.filter(item=>typeof item?.name==='string'&&(item.cents===null||Number.isSafeInteger(item.cents)&&item.cents>=0)):[];
      if (Array.isArray(cutTypes) && cutTypes.every(tipo => typeof tipo === 'string')) {
        return { ...lerEstilos(notes.slice(0, i)), cutTypes, cutPrices };
      }
    } catch {
      // Mantém as observações originais caso não contenham uma lista válida.
    }
  }
  return { ...lerEstilos(notes), cutTypes: [] };
}

function lerEstilos(notes) {
  const i = notes.lastIndexOf(marcadorEstilos);
  if (i >= 0) {
    try {
      const estilos = JSON.parse(notes.slice(i + marcadorEstilos.length));
      if (Array.isArray(estilos) && estilos.every(estilo => estilo?.id && estilo?.modelo && estilo?.tipo)) {
        return { notes: notes.slice(0, i), estilos };
      }
    } catch {
      // Preserva o texto quando o conteúdo não é um catálogo válido.
    }
  }
  return { notes, estilos: [] };
}

function writeClientNotes({ notes, cutTypes, cutPrices, estilos }) {
  return (notes || '') +
    (estilos?.length ? marcadorEstilos + JSON.stringify(estilos) : '') +
    (cutTypes?.length ? marcador + JSON.stringify(cutPrices?.length?{types:cutTypes,prices:cutPrices}:cutTypes) : '');
}

async function gravarEstilosClienteDb(atual, estilos) {
  const antes = atual.storedNotes===undefined?writeClientNotes(atual):atual.storedNotes;
  const depois = writeClientNotes({ ...atual, estilos });
  let consulta = G.from('clients').update({ notes: depois }).eq('id', atual.id);
  consulta = antes ? consulta.eq('notes', antes) : consulta.or('notes.is.null,notes.eq.');
  const { data, error } = await consulta.select('id').maybeSingle();
  if (error || !data) {
    return { ok: false, error: 'Não foi possível salvar. Atualize os dados do cliente e tente novamente.' };
  }
  return { ok: true };
}

async function salvarEstilosCliente(id, estilo, excluir = false) {
  const atual = K.clients.find(c => c.id === id);
  if (!atual) return { ok: false, error: 'Cliente não encontrado.' };
  const estilos = atual.estilos || [];
  const existente = estilos.some(item => item.id === estilo.id);
  const atualizados = excluir
    ? estilos.filter(item => item.id !== estilo.id)
    : existente
      ? estilos.map(item => item.id === estilo.id ? estilo : item)
      : [...estilos, { ...estilo, id: hp('estilo') }];
  if (G && fp() === 'real') {
    const resultado = await gravarEstilosClienteDb(atual, atualizados);
    if (!resultado.ok) return resultado;
  }
  K = {
    ...K,
    clients: K.clients.map(c => c.id === id ? { ...c, estilos: atualizados, storedNotes:writeClientNotes({...c,estilos:atualizados}) } : c),
  };
  up();
  return { ok: true };
}

