    const footer='Confira itens, quantidades, valores e prazos. Após ler todas as partes, responda “Confirmo o resumo '+reference+'” ou informe o item e a correção necessária.';
    const body=selected.map((item,index)=>[String(index+1)+'. '+item.label,...item.lines.filter(Boolean)].join('\n')).join('\n\n');
